# tests/test_find_missing.py

import pytest

# Adjust this import to match your project/module name.
# from your_module import find_missing


def find_missing(nums: list) -> int:
    """Find missing number in [0..n] sequence."""
    n = len(nums)
    return n * (n + 1) // 2 - sum(nums)


@pytest.mark.parametrize(
    ("nums", "expected"),
    [
        ([3, 0, 1], 2),
        ([0, 1], 2),
        ([9, 6, 4, 2, 3, 5, 7, 0, 1], 8),
        ([1, 2, 3], 0),
        ([0, 1, 2, 3], 4),
    ],
)
def test_find_missing_happy_path(nums, expected):
    assert find_missing(nums) == expected


@pytest.mark.parametrize(
    ("nums", "expected"),
    [
        ([], 0),       # Missing 0 from range [0..0]
        ([0], 1),      # Missing n
        ([1], 0),      # Missing 0
    ],
)
def test_find_missing_edge_cases(nums, expected):
    assert find_missing(nums) == expected


def test_find_missing_large_input():
    n = 10_000
    missing = 6789
    nums = [i for i in range(n + 1) if i != missing]

    assert find_missing(nums) == missing


def test_find_missing_raises_type_error_for_none():
    with pytest.raises(TypeError):
        find_missing(None)


def test_find_missing_raises_type_error_for_non_numeric_values():
    with pytest.raises(TypeError):
        find_missing([0, 1, "2", 3])
